$ErrorActionPreference = 'Stop'
$target = 'C:\dev\nial_diary\lib\main.dart'
if (Test-Path -LiteralPath $target) {
  throw 'main.dart already exists. Nothing overwritten. Stop and check the existing file.'
}
$parent = Split-Path -Parent $target
if (!(Test-Path -LiteralPath $parent -PathType Container)) {
  throw 'Project lib folder does not exist. No changes made.'
}
$encoded = @'

'@
$bytes = [Convert]::FromBase64String($encoded.Trim())
$sha = [Security.Cryptography.SHA256]::Create()
try {
  $hash = ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-', '')
} finally { $sha.Dispose() }
if ($hash -ne 'F5AE5CE5256814BADB4565A6AD6E0C5FB9C034496AD8C90A4A9E99A42139CF50') { throw 'Recovery data verification failed. No changes made.' }
$stream = [IO.File]::Open($target, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
try { $stream.Write($bytes, 0, $bytes.Length) } finally { $stream.Dispose() }
Write-Host 'SUCCESS: original uploaded voice-enabled main.dart restored. Other files were not changed.'
Get-Item -LiteralPath $target | Select-Object FullName, Length
